def rule_fn(row, col):
    if col != 'ProviderNumber':
        return False
    val = str(row.get('ProviderNumber', '')).strip()
    return not (val.isdigit() and len(val) == 5)

def rule_fn(row, col):
    if col != 'MeasureCode':
        return False
    allowed = {
        'scip-card-2','scip-inf-1','scip-inf-2','scip-inf-3','scip-inf-4','scip-inf-6',
        'scip-vte-1','scip-vte-2',
        'ami-1','ami-2','ami-3','ami-4','ami-5','ami-7a','ami-8a',
        'hf-1','hf-2','hf-3','hf-4',
        'pn-2','pn-3b','pn-4','pn-5c','pn-6','pn-7'
    }
    val = str(row.get('MeasureCode','')).strip().lower()
    return val not in allowed

def rule_fn(row, col):
    if col != 'Stateavg':
        return False
    state = str(row.get('State','')).strip().lower()
    code = str(row.get('MeasureCode','')).strip().lower()
    val = str(row.get('Stateavg','')).strip().lower()
    if not state or not code or not val:
        return True
    expected = f"{state}_{code}"
    return val != expected

def rule_fn(row, col):
    if col != 'EmergencyService':
        return False
    val = str(row.get('EmergencyService','')).strip().lower()
    return val not in {'yes','no'}

def rule_fn(row, col):
    if col != 'HospitalType':
        return False
    val = str(row.get('HospitalType','')).strip().lower()
    return val != 'acute care hospitals'

def rule_fn(row, col):
    if col not in {'Score','Sample'}:
        return False
    score = str(row.get('Score','')).strip().lower()
    sample = str(row.get('Sample','')).strip().lower()
    try:
        count = int(sample.split()[0])
    except Exception:
        return True
    if count == 0:
        return score != 'empty'
    else:
        return score == 'empty'
